class.description:
An [ECSSystem] declares the events it is interested in and processes them in one place, the way CryEngine entity components declare an event mask and implement [code]ProcessEvent[/code]. Extend it in a script, return the wanted events from [method _get_events] (engine lifecycle events such as [constant ECSWorld.EVENT_ENTITY_CREATE], [constant ECSWorld.EVENT_UPDATE], [constant ECSWorld.EVENT_FIXED_UPDATE], [constant ECSWorld.EVENT_LATE_UPDATE], networking events, or custom events) and handle them in [method _process_event]. Register it with [method ECSWorld.add_system_object].
[codeblock]
class_name HealthSystem
extends ECSSystem

var dying: ECSQuery

func _get_events() -> Array:
    return [ECSWorld.EVENT_ENTITY_CREATE, ECSWorld.EVENT_FIXED_UPDATE, &"damage"]

func _get_component_filter() -> Array:
    return [&"Health"] # Entity events only for entities with Health.

func _on_registered() -> void:
    dying = get_world().query([&"Health"])

func _process_event(event: Dictionary) -> void:
    match event.event:
        ECSWorld.EVENT_ENTITY_CREATE:
            print("new entity with Health: ", event.entity)
        ECSWorld.EVENT_FIXED_UPDATE:
            for e in dying.get_entities():
                if get_world().get_field(e, &"Health", &"value") <= 0:
                    get_world().defer_destroy_entity(e)
        _:
            if event.name == &"damage":
                var w := get_world()
                w.set_field(event.entity, &"Health", &"value", w.get_field(event.entity, &"Health", &"value") - event.payload)
[/codeblock]
